<script setup lang="ts">
import { artworkURL } from './artwork'
import { computed, ref, watch, onMounted, toRefs, nextTick, onBeforeUnmount } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { musicApi } from './core'
import type { Track, ExportData, CatalogueSource } from './core'
import { useMusic } from './stores/music'
import { useOverlay } from './stores/overlay'
import Icon from './ui/Icon.vue'
import TrackRows from './ui/TrackRows.vue'
import PlaylistTracks from './ui/PlaylistTracks.vue'
import { createSourceSearch, explicitSearchQuery } from './source-search'
import { recommendationNote } from './interest-feed'
import MediaSourceBadge from './ui/MediaSourceBadge.vue'
import ActionState from './ui/ActionState.vue'
const music=useMusic(),overlay=useOverlay(),route=useRoute(),router=useRouter(),query=ref(''),shared=ref<ExportData|null>(null),shareError=ref('')
const interests=music.interests,interest=interests.state
const recommendedTracks=computed(()=>interest.items.map(item=>item.track)),recommendationNotes=computed(()=>Object.fromEntries(interest.items.map(item=>[item.track.id,recommendationNote(item)])))
const sourceSearch=createSourceSearch(musicApi,(query,source)=>interests.recordSearch(query,source)),{results,searching,searched,source:catalogueSource,error:searchError,resultQuery,resultSource}=toRefs(sourceSearch.state)
const searchInput=ref<HTMLInputElement|null>(null)
function refineSearch(){searchInput.value?.focus();searchInput.value?.select()}
const catalogueSources=ref<CatalogueSource[]>([{id:'netease',name:'网易云'}])
function sourceName(source:string){return catalogueSources.value.find(option=>option.id===source)?.name || source}
async function loadSources(){try{const options=await musicApi.catalogOptions();if(options.sources.length)catalogueSources.value=options.sources}catch{/* Default catalogue remains available if capability lookup is unavailable. */}}
function selectSource(source:string){sourceSearch.select(source);music.error='';if(query.value.trim())void search(false)}

const playlistBusy=ref(false)
const page=computed(()=>route.path.split('/')[1] || 'library'),selected=computed(()=>music.selected),p=music.player
const nextTracks=computed(()=>p.state.upcomingIndices.slice(0,3).map(index=>p.state.tracks[index]!))
const now=computed(()=>p.currentTrack),historyTracks=computed(()=>music.history.map(h=>h.track)),sharedTracks=computed(()=>shared.value?.playlists.flatMap(p=>p.tracks)||[])
const discovery=recommendedTracks,discovering=computed(()=>interest.loading),discoveryError=computed(()=>interest.error)
function discover(){return interests.loadRecommendations({refresh:true})}
let handledSearchURL='',pageGeneration=0,active=true,sourcesReady:Promise<void>|undefined
async function loadPage(){
 const generation=++pageGeneration,snapshot={path:page.value,fullPath:route.fullPath,query:{...route.query},token:String(route.params.token||'')}
 const current=()=>active&&generation===pageGeneration
 shared.value=null;shareError.value=''
 if(snapshot.path!=='search')sourceSearch.cancel()
 if(snapshot.path==='library'){
  if(snapshot.query.recommend==='1')music.selectedID=''
  await interests.loadRecommendations()
  if(current()&&snapshot.query.recommend==='1'){await nextTick();if(current()&&!document.hidden)document.getElementById('recommendations')?.scrollIntoView({block:'start'})}
  return
 }
 if(snapshot.path==='search'){
  void interests.loadSearches()
  const explicit=explicitSearchQuery(snapshot.query.q)
  if(explicit&&handledSearchURL!==snapshot.fullPath){
   await sourcesReady;if(!current())return
   query.value=explicit
   const source=typeof snapshot.query.source==='string'&&catalogueSources.value.some(s=>s.id===snapshot.query.source)?snapshot.query.source:'netease'
   sourceSearch.select(source);await search(true)
   if(current()&&query.value===explicit&&sourceSearch.state.resultQuery===explicit&&!sourceSearch.state.error&&!sourceSearch.state.searching)handledSearchURL=snapshot.fullPath
  }else if(!searched.value)void interests.loadRecommendations()
  return
 }
 if(snapshot.path==='history'){await music.loadHistory();return}
 if(snapshot.path==='shares'){await music.loadShares();return}
 if(snapshot.path==='share'){
  try{const result=await musicApi.shared(snapshot.token);if(current())shared.value=result}
  catch{if(current())shareError.value='分享暂时无法打开，请重试。'}
 }
}
onMounted(()=>{sourcesReady=loadSources();void loadPage()});watch(()=>route.fullPath,()=>{void loadPage()})
watch(query,value=>sourceSearch.edit(value),{flush:'sync'})
watch(()=>music.user?.id,()=>{pageGeneration++;sourceSearch.reset();query.value='';handledSearchURL='';void loadPage()},{flush:'sync'})
onBeforeUnmount(()=>{active=false;pageGeneration++;sourceSearch.dispose()})
async function search(explicit=true){await sourceSearch.run(query.value,explicit)}
function repeatSearch(item:{query:string,source:string}){query.value=item.query;if(catalogueSources.value.some(s=>s.id===item.source))sourceSearch.select(item.source);void search(true)}
function play(tracks:Track[],index=0){if(tracks.length)music.run(()=>p.playTracks(tracks,index))}
function choose(id:string){music.selectedID=id;router.push('/library')}
watch([page,()=>selected.value?.id],()=>playlistBusy.value=false)
function reorder(from:number,to:number){if(playlistBusy.value)return;const current=selected.value;if(!current)return;const ids=current.tracks.map(t=>t.id);const item=ids.splice(from,1)[0];if(item){ids.splice(to,0,item);music.update(current,ids)}}
function removeTrack(index:number){if(playlistBusy.value)return;if(selected.value)music.update(selected.value,selected.value.tracks.filter((_,i)=>i!==index).map(t=>t.id))}
async function rename(){if(!selected.value)return;const name=prompt('歌单的新名称',selected.value.name);if(name?.trim())await music.update(selected.value,selected.value.tracks.map(t=>t.id),name)}
function deletePlaylist(){if(selected.value&&confirm(`删除歌单「${selected.value.name}」？`))music.remove(selected.value)}
function scrollCollection(){if(document.hidden)return;document.querySelector('#collection')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function shareName(id:string){return music.playlists.find(p=>p.id===id)?.name || '单曲分享'}
const heading=computed(()=>({likes:'把喜欢，留在身边。',history:'最近，循环了什么？',queue:'下一首，交给自己。'}[page.value as 'likes']||''))
</script>
<template>
 <template v-if="page==='share'"><section v-if="shared" class="share-view"><span class="eyebrow">SHARED WITH YOU / 只读分享</span><h1>{{shared.playlists[0]?.name || '分享的音乐'}}</h1><p class="lead">好音乐，值得与你分享。复制之后，就能在自己的空间编辑。</p><button class="primary" @click="music.run(async()=>{await musicApi.copyShare(String(route.params.token));await music.refresh();router.push('/library');music.notify('歌单已复制到你的空间')})"><Icon name="plus" :size="18"/>复制到我的歌单</button><TrackRows :tracks="sharedTracks" @play="play(sharedTracks,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/></section><p v-else-if="shareError" class="notice error" role="alert">{{shareError}} <button @click="loadPage">重试</button></p><div v-else class="empty-state">正在打开分享…</div></template>
 <template v-else-if="page==='search'"><section class="page-heading"><span class="eyebrow">DISCOVER / 发现歌曲</span><h1>总有一首，正合心意。</h1><p class="lead">从歌曲、歌手或专辑开始，找到下一份喜欢。</p></section><div class="catalogue-source-row"><label for="catalogue-source">选择曲库</label><select id="catalogue-source" :value="catalogueSource" @change="selectSource(($event.target as HTMLSelectElement).value)"><option v-for="source in catalogueSources" :key="source.id" :value="source.id">{{source.name}}</option></select><span>选择曲目后按其来源播放，不自动换版本。</span></div><form class="search-box" @submit.prevent="search(true)"><Icon name="search" :size="24"/><input ref="searchInput" v-model="query" aria-label="搜索歌曲" placeholder="搜索歌曲、歌手、专辑" maxlength="200"/><button class="primary" :disabled="!query.trim()||searching">{{searching?'搜索中…':'搜索'}}</button></form><p class="listening-guide"><Icon name="play" :size="15"/><span>点封面或歌名播放，<strong>喜欢</strong>留住好歌，<strong>歌单</strong>收进收藏。</span></p><section v-if="interest.searches.length||interest.historyError" class="recent-searches" aria-label="最近搜索"><div class="section-heading"><h2>最近搜索</h2><button class="subtle" :disabled="interest.historyLoading||!interest.searches.length" @click="interests.clearSearches()">清空搜索记录</button></div><p v-if="interest.historyError" class="muted">{{interest.historyError}} <button class="subtle" @click="interests.loadSearches({refresh:true})">重新读取记录</button></p><div v-if="interest.searches.length" class="search-chips"><button v-for="item in interest.searches" :key="`${item.source}:${item.query}`" class="search-chip" @click="repeatSearch(item)"><span>{{item.query}}</span><small>{{sourceName(item.source)}}</small></button></div><p v-else class="muted">主动搜索的关键词会留在自己的音乐空间。</p></section><ActionState v-if="searching" title="正在搜索歌曲" :description="results.length?'正在寻找新结果，仍可播放下方已有歌曲。':'找到曲目后，点封面即可开始播放。'" icon="search" busy><button class="subtle" @click="sourceSearch.cancel()">取消本次搜索</button></ActionState><p v-if="searchError" class="notice error" role="alert">{{searchError}} <button @click="search(true)">重试搜索</button></p><div v-if="searched" class="section-heading"><h2>搜索结果 <small>{{results.length}}</small></h2><span class="muted">“{{resultQuery}}” · {{sourceName(resultSource)}}</span></div><template v-if="!searched&&!searching&&!searchError&&catalogueSource==='netease'"><div class="section-heading"><h2>先听听这些</h2><span class="muted">曲库信息 · 播放时确认音源</span></div><ActionState v-if="discovering&&!discovery.length" title="正在找可以开始听的歌" description="曲目载入中，也可以直接搜索歌名或歌手。" icon="search" busy/><p v-if="discoveryError" class="notice error" role="alert">{{discoveryError}} <button @click="discover">重试</button></p><ActionState v-if="!discovering&&!discoveryError&&!discovery.length" title="先搜索一首喜欢的歌" description="当前还没有合适的发现曲目，可以试试歌名或歌手。" icon="search"><button class="subtle" @click="refineSearch">输入关键词</button></ActionState><TrackRows :tracks="discovery" @play="play(discovery,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/></template><div v-else-if="!searched&&!searching&&!searchError" class="catalogue-source-empty"><h2>在{{sourceName(catalogueSource)}}里，找一首喜欢的歌。</h2><p>歌曲的专辑、现场、伴奏与试听版本各有独立标识，请确认版本后播放。</p><button class="subtle" @click="query='小星星 纯音乐';search()">试听公开曲库示例 →</button></div><TrackRows v-else :tracks="results" @play="play(results,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/><ActionState v-if="searched&&!results.length&&!searching&&!searchError" title="没有找到这首歌" description="试试更短的歌名、歌手名，或切换曲库再搜索。" icon="search"><button class="subtle" @click="refineSearch">修改关键词 <Icon name="arrow" :size="16"/></button></ActionState></template>
 <template v-else-if="page==='play'"><section class="page-heading compact"><span class="eyebrow">NOW PLAYING / 正在播放</span><h1>{{now?.title || '给此刻，选一首歌。'}}</h1><p class="lead">把节奏留给自己。</p></section><section class="now-playing"><div class="now-cover"><img :src="artworkURL(now?.picture)" alt="专辑封面"/><div class="now-cover-shadow"/></div><div class="now-information"><span class="eyebrow">{{p.state.resolutionStatus==='preview'?'PREVIEW / 当前仅可试听':'YOUR OWN RHYTHM'}}</span><h2>{{now?.title || '还没有选择歌曲'}}</h2><p>{{now?.artist || '去发现下一首喜欢的歌。'}}</p><small>{{now?sourceName(now.source):''}}{{now?.album?' · '+now.album:''}}</small><MediaSourceBadge v-if="now" :info="p.state.sourceInfo" :trackID="now.id" :loading="p.state.loading"/><div class="large-controls"><button class="subtle shuffle-control" :aria-label="p.state.shuffle?'关闭随机播放':'开启随机播放'" :aria-pressed="p.state.shuffle" @click="p.setShuffle(!p.state.shuffle)"><Icon name="shuffle" :size="18"/>{{p.state.shuffle?'随机已开':'随机播放'}}</button><button class="icon-button" aria-label="上一首" :disabled="!now" @click="p.previous()"><Icon name="previous" :size="26"/></button><button class="play-button" :aria-label="p.state.playing?'暂停':'播放'" :disabled="!now" @click="p.toggle()"><Icon :name="p.state.playing?'pause':'play'" :size="26"/></button><button class="icon-button" aria-label="下一首" :disabled="!now" @click="p.next()"><Icon name="next" :size="26"/></button><button class="icon-button" :class="{liked:now&&music.likedIDs.has(now.id)}" :aria-label="now&&music.likeState.pending.includes(now.id)?'正在保存喜欢':'喜欢当前歌曲'" :aria-busy="!!now&&music.likeState.pending.includes(now.id)" :disabled="!now||music.likeState.pending.includes(now.id)" @click="now&&music.toggleLike(now)"><Icon name="heart" :size="24"/></button></div><div class="button-row"><button class="subtle" :disabled="!now" @click="overlay.lyrics=true"><Icon name="lyrics" :size="18"/>打开歌词</button><button class="subtle" :disabled="!now" @click="now&&overlay.add(now)"><Icon name="plus" :size="18"/>加入歌单</button><a class="subtle" href="/play" target="_blank" rel="noopener noreferrer">独立窗口 ↗</a></div><p class="fine-print">持续聆听建议保留播放器页。锁屏与后台播放取决于浏览器和系统。</p></div></section><div class="section-heading"><h2>{{p.state.shuffle?'本轮待播':'接下来播放'}} <small>{{p.state.upcomingIndices.length}}</small></h2><RouterLink to="/queue">查看队列 →</RouterLink></div><p v-if="p.state.shuffle&&p.state.repeat==='all'&&!p.state.upcomingIndices.length" class="muted">本轮结束后会开始新一轮随机播放。</p><TrackRows :tracks="nextTracks" @play="p.playAt(p.state.upcomingIndices[$event]!)" @add="overlay.add" @share="overlay.share('track',$event.id)"/></template>
 <template v-else-if="page==='queue'||page==='likes'||page==='history'"><section class="page-heading"><span class="eyebrow">{{page==='queue'?'UP NEXT / 当前设备':page==='likes'?'YOUR FAVORITES / 喜欢的歌':'RECENTLY PLAYED / 最近播放'}}</span><h1>{{heading}}</h1><p class="lead">{{page==='queue'?'队列和位置自动保存。随机开关与本轮顺序保存在当前身份的这个浏览器。':page==='likes'?'那些让你按下爱心的瞬间。':'每一次聆听，都有迹可循。'}}</p></section><div class="section-heading"><h2>{{page==='queue'?'待播队列':page==='likes'?'喜欢的歌':'最近播放'}} <small>{{page==='queue'?p.state.tracks.length:page==='likes'?music.likes.length:music.history.length}}</small></h2><div class="button-row"><template v-if="page==='queue'"><button class="subtle shuffle-control" :aria-label="p.state.shuffle?'关闭随机播放':'开启随机播放'" :aria-pressed="p.state.shuffle" @click="p.setShuffle(!p.state.shuffle)"><Icon name="shuffle" :size="17"/>{{p.state.shuffle?'随机已开':'随机播放'}}</button><button class="subtle" :aria-pressed="p.state.repeat!=='off'" @click="p.setRepeat(p.state.repeat==='off'?'all':p.state.repeat==='all'?'one':'off')"><Icon name="repeat" :size="17"/>{{p.state.repeat==='off'?'开启队列循环':p.state.repeat==='all'?'切换单曲循环':'关闭循环'}}</button><button class="subtle" @click="p.reloadQueue()">恢复服务器队列</button><button class="subtle" @click="p.clear()">清空队列</button></template><button v-if="page==='history'" class="subtle" @click="music.clearHistory()">清空历史</button><button v-if="page==='likes'&&music.likes.length" class="primary small" @click="play(music.likes)"><Icon name="play" :size="15"/>播放全部</button></div></div><p v-if="page==='queue'&&p.state.shuffle" class="muted" role="status">随机播放已开启，每轮按待播项遍历。下面保留原队列顺序，关闭随机后从当前曲目往后播放。</p><TrackRows v-if="page==='queue'" :tracks="p.state.tracks" editable queue @play="p.playAt($event)" @remove="p.removeAt($event)" @move="(from,to)=>p.move(from,to)" @add="overlay.add" @share="overlay.share('track',$event.id)"/><TrackRows v-else :tracks="page==='likes'?music.likes:historyTracks" @play="play(page==='likes'?music.likes:historyTracks,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/><div v-if="!(page==='queue'?p.state.tracks.length:page==='likes'?music.likes.length:music.history.length)" class="empty-state"><span class="empty-symbol"><Icon :name="page==='queue'?'queue':page==='likes'?'heart':'history'" :size="36"/></span><h2>{{page==='queue'?'留一点期待给下一首。':page==='likes'?'遇见喜欢，记得留个爱心。':'音乐会在这里留下足迹。'}}</h2><RouterLink to="/search">去发现歌曲 →</RouterLink></div></template>
 <template v-else-if="page==='shares'"><section class="page-heading"><span class="eyebrow">SHARED BY YOU / 分享管理</span><h1>分享喜欢，保留选择。</h1><p class="lead">分享链接只读，30 天后过期。撤销之后，原链接立即失效。</p></section><div v-for="share in music.shares" :key="share.id" class="share-row"><span class="share-icon"><Icon name="share"/></span><div><strong>{{shareName(share.targetID)}}</strong><small>{{share.kind==='playlist'?'歌单':'单曲'}} · {{share.revoked?'已撤销':'只读链接'}}</small></div><button class="subtle" :disabled="share.revoked" @click="music.revoke(share.id)">{{share.revoked?'已撤销':'撤销分享'}}</button></div><div v-if="!music.shares.length" class="empty-state"><Icon name="share" :size="40"/><h2>把好音乐分享给朋友。</h2><p>从歌曲或歌单创建分享链接。</p></div></template>
 <template v-else-if="selected"><button class="back-link" :disabled="playlistBusy" @click="music.selectedID=''"><Icon name="arrow" :size="17"/>我的音乐</button><section class="playlist-header" :inert="playlistBusy||undefined"><img :src="artworkURL(selected.tracks[0]?.picture)" alt="歌单封面"/><div><span class="eyebrow">YOUR PRIVATE PLAYLIST / 自有歌单</span><h1>{{selected.name}}</h1><p class="lead">{{selected.tracks.length}} 首歌曲 · 私有收藏</p><div class="button-row"><button class="primary" :disabled="!selected.tracks.length" @click="play(selected.tracks)"><Icon name="play" :size="17"/>播放歌单</button><button class="subtle" @click="rename"><Icon name="edit" :size="16"/>重命名</button><button class="subtle" @click="overlay.share('playlist',selected.id)"><Icon name="share" :size="16"/>只读分享</button><button class="icon-button" aria-label="删除歌单" @click="deletePlaylist"><Icon name="trash" :size="18"/></button></div></div></section><PlaylistTracks :key="`${music.user?.id}:${selected.id}`" :playlist="selected" @busy="playlistBusy=$event" @play="play" @move="reorder" @remove="removeTrack"/><div v-if="!selected.tracks.length" class="empty-state"><Icon name="music" :size="38"/><h2>给这张歌单，添一点旋律。</h2><p>搜索一首歌，点歌曲旁的「歌单」，再选择这张歌单。</p><RouterLink to="/search">搜索歌曲 →</RouterLink></div></template>
 <template v-else><div class="library-home"><section class="library-hero"><div><span class="eyebrow">YOUR MUSIC. YOUR SPACE.</span><h1>生活有很多节奏，<br/>这一刻，听自己的。</h1><p>从一首歌开始，把喜欢慢慢收进自己的空间。</p><div class="hero-actions"><RouterLink class="primary" to="/search">发现下一首 <Icon name="arrow" :size="18"/></RouterLink><button class="subtle" @click="scrollCollection">我的歌单 <Icon name="down" :size="16"/></button></div></div><div class="hero-art" aria-hidden="true"><div class="record-sleeve"><span>THE PERSONAL COLLECTION</span><div class="record"><div>BetaGo<small>SIDE A / 33⅓</small></div></div><i>PLAY SOMETHING YOU LOVE.</i></div></div></section><section class="library-summary"><RouterLink to="/likes"><strong>{{music.likes.length.toString().padStart(2,'0')}}</strong><span>首喜欢</span></RouterLink><span class="summary-divider"/><button @click="scrollCollection()"><strong>{{music.playlists.length.toString().padStart(2,'0')}}</strong><span>张歌单</span></button><span class="summary-divider"/><RouterLink to="/history"><strong>{{music.history.length.toString().padStart(2,'0')}}</strong><span>首最近播放</span></RouterLink><span class="library-caption">COLLECT THE MOMENTS.</span></section><section id="collection"><div class="section-heading"><h2>我的歌单 <small>{{music.playlists.length}}</small></h2><button class="subtle" @click="overlay.create()"><Icon name="plus" :size="17"/>新建歌单</button></div><div v-if="music.playlists.length" class="playlist-grid"><button v-for="(playlist,index) in music.playlists" :key="playlist.id" class="playlist-card" @click="choose(playlist.id)"><div class="playlist-art" :class="`cover-${index%4}`"><img :src="artworkURL(playlist.tracks[0]?.picture)" alt="" loading="lazy"/><span class="playlist-card-play"><Icon name="play" :size="22"/></span></div><strong>{{playlist.name}}</strong><span>{{playlist.tracks.length}} 首 · 私有歌单</span></button><button class="new-playlist-card" @click="overlay.create()"><span><Icon name="plus" :size="28"/></span><strong>{{music.playlists.length?'再留一个位置。':'创建你的第一张歌单'}}</strong><small>为某段心情，留一张歌单。</small></button></div><p v-else class="collection-empty">还没有歌单。找到喜欢的歌，点「歌单」就能收进这里，也可以先新建一张。</p></section><section id="recommendations" class="library-discovery recommendations-section"><div class="section-heading"><h2>{{interest.personalized?'为你推荐':'听听这些'}}</h2><button class="subtle" :disabled="interest.loading" @click="interests.loadRecommendations({refresh:true})">{{interest.loading?'正在寻找…':'刷新推荐'}}</button></div><p class="muted">{{interest.personalized?'根据这个音乐空间的喜欢、最近播放和主动搜索推荐。':'先从公开曲库开始，喜欢与聆听之后，再发现合心意的歌。'}}</p><ActionState v-if="interest.loading&&!interest.items.length" title="正在寻找下一首" description="推荐载入中，也可以先搜索一首想听的歌。" icon="music" busy><RouterLink to="/search" class="subtle">去搜索 <Icon name="arrow" :size="16"/></RouterLink></ActionState><p v-if="interest.notice" class="muted" role="status">{{interest.notice}}</p><p v-if="interest.error" class="notice error" role="alert">{{interest.error}} <button @click="interests.loadRecommendations({refresh:true})">重试推荐</button><RouterLink to="/search">去搜索 →</RouterLink></p><TrackRows :tracks="recommendedTracks" :notes="recommendationNotes" @play="play(recommendedTracks,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/><ActionState v-if="!interest.loading&&!interest.items.length&&!interest.error" title="从一首喜欢的歌开始" description="暂时没有合适的推荐。先搜索、聆听或点喜欢，再回来发现。" icon="search"><RouterLink to="/search" class="subtle">搜索歌曲 <Icon name="arrow" :size="16"/></RouterLink></ActionState></section><section v-if="music.likes.length" class="library-favorites"><div class="section-heading"><h2>喜欢的歌</h2><RouterLink to="/likes">查看全部 →</RouterLink></div><TrackRows :tracks="music.likes.slice(0,4)" @play="play(music.likes,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/></section></div></template>
</template>

